<style>
  .guide-loading {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
    pointer-events: none;
    /* 600 ms in, after a 350 ms wait, on the shared clock. */
    animation: guide-loading-in calc(var(--duration-scene) * 0.75)
      var(--ease-standard, ease-out) var(--duration-dramatic) both;
  }
  .turn {
    width: min(46%, 46vh, 340px);
    aspect-ratio: 1;
    animation: guide-loading-turn 36s linear infinite;
    will-change: transform;
  }
  svg {
    display: block;
    width: 100%;
    height: 100%;
    overflow: visible;
  }
  path {
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-dasharray: 1 1;
    animation: guide-loading-trace 4.2s linear infinite;
  }
  /* The app's motion blue and red, pulled toward the page's ink so they
     read on the Guide's white sheets and on its dark run pages alike. */
  .left {
    --hand: color-mix(in oklab, #6366f1 78%, currentColor);
  }
  .right {
    --hand: color-mix(in oklab, #ef4444 82%, currentColor);
  }
  /* The Overture's glow pass, as a soft shadow in the hand's colour. */
  .left,
  .right {
    stroke: var(--hand);
    filter: drop-shadow(
      0 0 3px color-mix(in oklab, var(--hand) 55%, transparent)
    );
  }
  path {
    stroke-width: 2.2;
  }
  @keyframes guide-loading-in {
    from {
      opacity: 0;
    }
    to {
      opacity: 0.85;
    }
  }
  @keyframes guide-loading-turn {
    to {
      transform: rotate(1turn);
    }
  }
  /* Drawn, held, then cleared forwards, so each pass starts where the last
     one ended. */
  @keyframes guide-loading-trace {
    0% {
      stroke-dashoffset: 1;
    }
    62% {
      stroke-dashoffset: 0;
    }
    80% {
      stroke-dashoffset: 0;
    }
    100% {
      stroke-dashoffset: -1;
    }
  }
  /* Reduced motion: the figure stands finished and breathes. */
  @media (prefers-reduced-motion: reduce) {
    .turn {
      animation: guide-loading-breathe 2.4s ease-in-out infinite alternate;
    }
    path {
      animation: none;
      stroke-dashoffset: 0;
    }
  }
  @keyframes guide-loading-breathe {
    from {
      opacity: 0.55;
    }
    to {
      opacity: 1;
    }
  }
</style>
